solution.code:
#include <stdio.h>

int main() {
    for (int n = 2; n <= 30; n++) {
        int sum = 0;
        for (int d = 1; d < n; d++) {
            if (n % d == 0) {
                sum += d;
            }
        }
        if (sum == n) {
            printf("%d\n", n);
        }
    }
    return 0;
}
